WITH candidates AS (
    SELECT id FROM ifj_notify_send_log
    WHERE result <> 'STARTED' AND create_time < #{cutoff}
    ORDER BY create_time ASC, id ASC
    LIMIT #{limit}
)
DELETE FROM ifj_notify_send_log target
USING candidates
WHERE target.id = candidates.id

WITH candidates AS (
    SELECT id FROM ifj_notify_send_log
    WHERE result <> 'STARTED' AND create_time < #{cutoff}
    ORDER BY create_time ASC, id ASC
    LIMIT #{limit}
)
DELETE FROM ifj_notify_send_log WHERE id IN (SELECT id FROM candidates)

DELETE FROM ifj_notify_send_log
WHERE id IN (
    SELECT id FROM (
        SELECT id FROM ifj_notify_send_log
        WHERE result <> 'STARTED' AND create_time < #{cutoff}
        ORDER BY create_time, id
    ) WHERE ROWNUM <= #{limit}
)

WITH candidates AS (
    SELECT run_id FROM ifj_app_run
    WHERE status IN ('STOPPED', 'CRASHED')
      AND heartbeat_at < #{cutoff}
    ORDER BY heartbeat_at ASC, run_id ASC
    LIMIT #{limit}
)
DELETE FROM ifj_app_run target
USING candidates
WHERE target.run_id = candidates.run_id

WITH candidates AS (
    SELECT run_id FROM ifj_app_run
    WHERE status IN ('STOPPED', 'CRASHED')
      AND heartbeat_at < #{cutoff}
    ORDER BY heartbeat_at ASC, run_id ASC
    LIMIT #{limit}
)
DELETE FROM ifj_app_run WHERE run_id IN (SELECT run_id FROM candidates)

DELETE FROM ifj_app_run
WHERE run_id IN (
    SELECT run_id FROM (
        SELECT run_id FROM ifj_app_run
        WHERE status IN ('STOPPED', 'CRASHED') AND heartbeat_at < #{cutoff}
        ORDER BY heartbeat_at, run_id
    ) WHERE ROWNUM <= #{limit}
)

SET NOCOUNT ON;
DECLARE @triggers TABLE (id bigint PRIMARY KEY);
INSERT INTO @triggers (id) VALUES
(#{id});
DECLARE @instances TABLE (id bigint PRIMARY KEY);
INSERT INTO @instances (id) SELECT id FROM ifj_instance
WHERE trigger_id IN (SELECT id FROM @triggers);
DELETE FROM ifj_event_wait_operator WHERE wait_id IN (
    SELECT id FROM ifj_event_wait WHERE instance_id IN (SELECT id FROM @instances)
        OR root_instance_id IN (SELECT id FROM @instances));
DELETE FROM ifj_event_wait WHERE instance_id IN (SELECT id FROM @instances)
    OR root_instance_id IN (SELECT id FROM @instances);
DELETE FROM ifj_instance_log WHERE instance_id IN (SELECT id FROM @instances);
DELETE FROM ifj_dag_gateway_decision WHERE job_instance_id IN (SELECT id FROM @instances);
DELETE FROM ifj_runtime_command WHERE trigger_id IN (SELECT id FROM @triggers)
    OR instance_id IN (SELECT id FROM @instances) OR root_instance_id IN (SELECT id FROM @instances);
DELETE FROM ifj_trigger_work_item WHERE trigger_id IN (SELECT id FROM @triggers)
    OR root_instance_id IN (SELECT id FROM @instances);
SET NOCOUNT OFF;
DELETE FROM ifj_instance WHERE id IN (SELECT id FROM @instances);
